WITH valid_shipments AS (SELECT * FROM shipments WHERE shipped_date BETWEEN '2024-02-25' AND '2025-08-04' AND (status = 'RETURNED' OR status IN ('DELIVERED', 'LOST'))), agg AS (SELECT CASE WHEN status IN ('LOST', 'IN_TRANSIT') THEN 'priority' ELSE 'other' END AS status_group, ROUND(AVG(cost), 2) AS avg_cost FROM valid_shipments GROUP BY CASE WHEN status IN ('LOST', 'IN_TRANSIT') THEN 'priority' ELSE 'other' END) SELECT * FROM agg WHERE avg_cost > 33 ORDER BY status_group, avg_cost;
